function finishSession(id){const s=state.data.sessions.find(s=>s.id===id),entries=state.data.set_logs.filter(l=>l.sessionId===id).length+state.data.skill_logs.filter(l=>l.sessionId===id).length,elapsed=s.startedAt?Math.round((Date.now()-Date.parse(s.startedAt))/60000):0;modal(s.status==='completed'?'Update session summary':'Finish your session',`<form id="finish-form"><div class="form-grid"><label>Actual duration (minutes)<input type="number" name="duration" min="1" max="600" step="1" required value="${s.actualDurationMin??(elapsed>=5&&elapsed<=180?elapsed:'')}" placeholder="Time you actually trained"></label><label>Overall session RPE (0–10)<input type="number" name="rpe" min="0" max="10" step="0.5" required value="${s.sessionRpe??''}" placeholder="0 rest, 10 maximal"></label><label class="full">Session notes<textarea name="notes" placeholder="What felt strong? What needs adjusting?">${esc(s.completionNotes||'')}</textarea></label></div><p class="form-help">Session load = actual minutes × overall RPE. Enter your overall impression after the session; you can update it later.</p>${!entries&&!['ice','roller'].includes(s.kind)?'<label class="check-row mt-16"><input type="checkbox" name="withoutSets" required>Complete without individual exercise logs</label>':''}<div class="form-actions"><button class="btn btn-primary">Save completed session</button></div></form>`,`${entries} exercise entries saved · ${s.durationMin} minutes originally planned`);$('#finish-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await db.save('sessions',{...s,status:'completed',actualDurationMin:number(f,'duration'),sessionRpe:number(f,'rpe'),completionNotes:String(f.get('notes')||''),completedAt:s.completedAt||isoNow()});await refresh({render:false});await updateRecords();closeModal();await refresh();toast('Session completed. Next-session targets are updated.');}catch(err){toast(err.message,true);}});}
async function updateRecords(){
 const done=new Set(state.data.sessions.filter(s=>s.status==='completed').map(s=>s.id));
 for(const e of state.data.exercises.filter(e=>e.category==='strength')){
  const logs=state.data.set_logs.filter(l=>l.exerciseId===e.id&&done.has(l.sessionId)&&l.kind==='strength'&&epley(l.loadKg,l.reps));
  const old=state.data.personal_records.filter(p=>p.exerciseId===e.id&&p.type==='e1rm');
  const variants=new Set([...logs.map(l=>l.variant||'standard'),...old.map(p=>p.variant||'standard')]);
  for(const variant of variants){
   const best=logs.filter(l=>(l.variant||'standard')===variant).sort((a,b)=>epley(b.loadKg,b.reps)-epley(a.loadKg,a.reps))[0];
   const existing=old.find(p=>(p.variant||'standard')===variant);
   if(best){const value=epley(best.loadKg,best.reps);if(!existing||existing.value!==value||existing.sessionId!==best.sessionId)await db.save('personal_records',{...existing,exerciseId:e.id,type:'e1rm',variant,method:variant==='standard'?'Standard recorded setup':variant,value,unit:'kg',date:best.date,sessionId:best.sessionId,notes:'Epley estimate, not a tested maximum. '+(e.loadConvention||'')});}
   else if(existing)await db.remove('personal_records',existing.id);
  }
 }
}

function wellnessModal(){const existing=wellnessFor(state.date);modal('Your daily check-in',`<form id="wellness-form"><div class="form-grid"><label>Date<input type="date" name="date" value="${state.date}" required></label><label>Sleep (hours)<input name="sleepHours" type="number" min="0" max="16" step="0.25" required value="${existing?.sleepHours??''}" placeholder="7.5"></label>${[['sleepQuality','Sleep quality',1,5,'1 very poor, 5 excellent'],['energy','Energy',1,5,'1 exhausted, 5 energetic'],['soreness','Body soreness',0,10,'0 none, 10 very sore'],['mood','Mood',1,5,'1 low, 5 positive']].map(([key,label,min,max,hint])=>`<label>${label}<select name="${key}" required><option value="">Select</option>${Array.from({length:max-min+1},(_,i)=>i+min).map(n=>`<option value="${n}" ${existing?.[key]===n?'selected':''}>${n}${n===min?' · '+hint.split(', ')[0].replace(/^\d+ /,''):n===max?' · '+hint.split(', ')[1].replace(/^\d+ /,''):''}</option>`).join('')}</select><span class="form-help">${hint}</span></label>`).join('')}<label>Bodyweight (kg, optional)<input name="bodyweightKg" type="number" min="30" max="250" step="0.1" value="${existing?.bodyweightKg??''}" placeholder="75.5"></label><label>Wrist discomfort (0–10)<input name="wristPain" type="number" min="0" max="10" step="1" value="${existing?.wristPain??''}" placeholder="Optional symptom diary"></label><div class="checkbox-group full"><label class="check-row"><input name="wristWorse" type="checkbox" ${existing?.wristWorse?'checked':''}>Wrist feels worse than my usual baseline</label><label class="check-row"><input name="gripLimited" type="checkbox" ${existing?.gripLimited?'checked':''}>Grip is painful, weak or unreliable today</label><label class="check-row"><input name="illness" type="checkbox" ${existing?.illness?'checked':''}>I feel unwell or have illness symptoms</label></div><label class="full">Notes<textarea name="notes" placeholder="Late skate, travel, symptoms or anything useful">${esc(existing?.notes||'')}</textarea></label></div><div class="notice mt-16">Readiness combines sleep, energy, soreness, sleep quality and mood. Bodyweight and wrist discomfort do not change the numerical score. Symptoms can still override the workout.</div><div class="form-actions"><button class="btn btn-primary">Save check-in</button></div></form>`,prettyDate(state.date,{weekday:'long',day:'numeric',month:'long'}));$('#wellness-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),date=String(f.get('date')),old=wellnessFor(date);const row={...old,date,sleepHours:number(f,'sleepHours'),sleepQuality:number(f,'sleepQuality'),energy:number(f,'energy'),soreness:number(f,'soreness'),mood:number(f,'mood'),bodyweightKg:number(f,'bodyweightKg'),wristPain:number(f,'wristPain'),wristWorse:f.has('wristWorse'),gripLimited:f.has('gripLimited'),illness:f.has('illness'),notes:String(f.get('notes')||'')};row.readinessScore=readiness(row).score;try{await db.save('wellness_logs',row);state.date=date;closeModal();await refresh();toast('Check-in saved. Today’s recommendations are updated.');if(row.gripLimited)modal('Give your wrist a break','<p>Pause additional handling, shooting and painful grip work. Because your flares affect grip, arrange a hand or sports physiotherapist review and follow their loading plan.</p><p>If you currently cannot hold objects or move the wrist normally, seek prompt medical advice. The NHS wrist-pain guidance explains when to use NHS 111.</p><p class="mt-16"><a href="https://www.nhs.uk/symptoms/hand-pain/wrist-pain/" target="_blank" rel="noopener noreferrer">NHS wrist pain guidance</a></p><div class="form-actions"><button class="btn btn-primary" data-action="close-modal">Understood</button></div>');}catch(err){toast(err.message,true);}});}

function sessionOptions(id){const s=state.data.sessions.find(x=>x.id===id);modal('Make the plan fit',`<form id="session-options-form"><div class="form-grid"><label class="full">Session name<input name="title" value="${esc(s.title)}" required maxlength="150"></label><label>Scheduled date<input type="date" name="date" value="${s.date}" required></label><label>Planned minutes<input name="durationMin" type="number" min="5" max="240" value="${s.durationMin}" required></label><label>Planned RPE<input name="intensityRpe" type="number" min="1" max="10" step="0.5" value="${s.intensityRpe||6}" required></label><label>Status<select name="status"><option value="planned" ${s.status==='planned'?'selected':''}>Planned</option><option value="skipped" ${s.status==='skipped'?'selected':''}>Skipped</option>${s.status==='completed'?'<option value="completed" selected>Completed</option>':''}</select></label><label class="check-row full"><input type="checkbox" name="isGame" ${s.isGame?'checked':''}>This is a game or confirmed tryout</label><label class="check-row full"><input type="checkbox" name="optional" ${s.optional?'checked':''}>Optional session</label><label class="full">Reason or planning note<textarea name="rescheduleNote">${esc(s.rescheduleNote||'')}</textarea></label></div><div class="notice mt-16">A moved session is not duplicated. Skipped work is never added to tomorrow automatically. Marking a game reduces nearby off-ice work; review Friday and Sunday manually too.</div><div class="form-actions"><button class="btn btn-primary">Save changes</button></div></form>`,s.title);$('#session-options-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),date=String(f.get('date')),dow=new Date(date+'T12:00:00Z').getUTCDay();if(s.kind==='strength'&&dow===1&&date!==s.date)return toast('Monday is your no-gym day. Choose another date.',true);try{if(date!==s.date&&[...state.data.set_logs,...state.data.skill_logs,...state.data.test_results].some(l=>l.sessionId===id))throw new Error('This session already has dated logs. Reschedule an unlogged session so your recorded history stays consistent.');const w=weekFor(date);await db.save('sessions',{...s,title:String(f.get('title')),originalDate:s.originalDate||s.date,date,weekId:w?.id||s.weekId,phaseId:w?.phaseId||s.phaseId,durationMin:number(f,'durationMin'),intensityRpe:number(f,'intensityRpe'),status:String(f.get('status')),isGame:f.has('isGame'),optional:f.has('optional'),rescheduleNote:String(f.get('rescheduleNote')||'')});closeModal();await refresh({render:false});await updateRecords();await refresh();toast('Session updated.');}catch(err){toast(err.message,true);}});}
function addSession(){const examples=[...new Map(state.data.sessions.filter(s=>s.kind!=='testing'&&s.kind!=='skills').map(s=>[s.templateId,s])).values()];modal('Add an extra session',`<form id="add-session-form"><div class="form-grid"><label>Date<input type="date" name="date" value="${state.date}" required></label><label>Session type<select name="template"><option value="custom-ice">Extra ice practice / game</option><option value="custom-conditioning">Extra conditioning</option>${examples.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></label><label class="full">Name (optional)<input name="title" placeholder="Use the selected template name" maxlength="150"></label></div><div class="notice mt-16">Extra sessions are optional. Copying a template does not add any completed data. Avoid adding hard conditioning on top of a hard skate.</div><div class="form-actions"><button class="btn btn-primary">Add to programme</button></div></form>`);$('#add-session-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),date=String(f.get('date')),template=state.data.sessions.find(s=>s.id===f.get('template')),w=weekFor(date)||state.data.weeks[0],id=uid();if(template?.kind==='strength'&&new Date(date+'T12:00:00Z').getUTCDay()===1)return toast('Monday is your no-gym day. Choose another date.',true);try{const copy=template?structuredClone(template):{kind:f.get('template')==='custom-ice'?'ice':'conditioning',templateId:String(f.get('template')),title:f.get('template')==='custom-ice'?'Extra ice practice':'Extra conditioning',durationMin:30,intensityRpe:5,environment:'EITHER',warmup:[],cooldown:[],notes:'An extra session you added. Log its actual time and session RPE.'};for(const key of ['createdAt','updatedAt','changeId','completedAt','actualDurationMin','sessionRpe','startedAt','completionNotes','warmupDone','cooldownDone'])delete copy[key];await db.save('sessions',{...copy,id,weekId:w.id,phaseId:w.phaseId,date,title:String(f.get('title')||copy.title),extra:true,optional:true,status:'planned',isGame:false});if(template){await db.saveMany('session_exercises',sessionExercises(template.id).map(x=>{const y=structuredClone(x);for(const k of ['createdAt','updatedAt','changeId'])delete y[k];return {...y,id:uid(),sessionId:id};}));}closeModal();await refresh();location.hash='session/'+id;toast('Extra session added.');}catch(err){toast(err.message,true);}});}
function swapExercise(id){
 const sx=state.data.session_exercises.find(x=>x.id===id);
 if([...state.data.set_logs,...state.data.skill_logs,...state.data.test_results].some(l=>l.sessionExerciseId===id||l.sessionId===sx.sessionId&&l.exerciseId===sx.exerciseId))return toast('Saved entries keep their original exercise. Choose an alternative before logging this block, or remove those entries first.',true);
 const e=exById(sx.exerciseId),choices=exerciseChoices(sx,state.data.exercises,seed.session_exercises);
 const metricLabels={reps:'Repetitions',seconds:'Seconds',distanceM:'Metres',contacts:'Foot contacts'};
 modal('Choose an alternative',`<p>Replace <strong>${esc(e.name)}</strong> for this session.</p><form id="swap-form" class="mt-16"><label>Search exercises<input name="search" type="search" placeholder="Exercise, muscle or equipment"></label><label class="mt-16">Category<select name="category"><option value="">All categories</option>${[...new Set([...choices.keys()].map(id=>exById(id).category))].sort().map(c=>`<option value="${esc(c)}" ${c===e.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="mt-16">Exercise<select name="exerciseId" required></select></label><p id="swap-count" class="small muted mt-8" aria-live="polite"></p><div id="swap-dose" class="notice mt-16"></div><div id="swap-targets"></div><label class="mt-16">Equipment / variant label<input name="variant" placeholder="Optional, e.g. gym A machine model, seat 3" maxlength="100"></label><div id="swap-confirmation"></div><div class="form-actions"><button class="btn btn-primary">Use this movement</button></div></form>`);
 const form=$('#swap-form');
 const update=()=>{
  const option=choices.get(form.elements.exerciseId.value),next=option&&exById(option.exerciseId);
  form.querySelector('button.btn-primary').disabled=!next;
  if(!next){$('#swap-dose').textContent='No matching exercises. Try another search or category.';$('#swap-targets').innerHTML='';$('#swap-confirmation').innerHTML='';form.elements.variant.required=false;return;}
  const t=option.targetSets?.[0]||{},metrics=targetMetrics(next),simple=!t.rounds&&!t.workSec;
  $('#swap-dose').innerHTML=`<strong>${esc(next.name)}</strong><p>${esc(next.equipment.join(' · '))}</p>${option.targetSets.length?`<ol class="small mt-8">${option.targetSets.map(t=>`<li>${esc(targetText(t,next))} · ${t.restSec||0}s rest</li>`).join('')}</ol>`:'<p>Set your targets below before choosing this movement.</p>'}<p class="small">${esc(next.quality)} · ${esc(next.muscles.join(', '))}</p><p class="small mt-8">This changes only this block. Review the targets to fit the session’s ${sx.estimatedBlockMin||'planned'} minute block.</p>`;
  const metric=metrics.find(key=>t[key])||(['CO02','CO05','ST15'].includes(next.code)?'seconds':metrics[0]);
  $('#swap-targets').innerHTML=`<label class="check-row mt-16"><input name="editTargets" type="checkbox" ${!option.targetSets.length?'checked disabled':''}>${option.targetSets.length?'Edit targets':'Set targets'}</label><div id="swap-custom" class="form-grid mt-16"><label>Sets<input name="sets" type="number" min="1" max="20" value="${option.targetSets.length||sx.targetSets.length}" required></label><label>Target unit<select name="metric">${metrics.map(key=>`<option value="${key}" ${key===metric?'selected':''}>${metricLabels[key]}</option>`).join('')}</select></label><label>Amount per set / side<input name="amount" type="number" min="1" max="3600" step="1" value="${simple?t[metric]||'':''}" required></label><label>Sides<select name="sides"><option value="1">One / both together</option><option value="2" ${t.sides===2?'selected':''}>Left and right</option></select></label><label>Rest between sets (sec)<input name="restSec" type="number" min="0" max="1200" value="${t.restSec||0}" required></label><label>Effort (RPE)<input name="rpe" type="number" min="1" max="10" step="0.5" value="${t.rpe||sx.targetSets[0]?.rpe||5}" required></label></div>`;
  const toggle=()=>{const edit=form.elements.editTargets.checked;$('#swap-custom').hidden=!edit;for(const input of $('#swap-custom').querySelectorAll('input,select'))input.disabled=!edit;};
  form.elements.editTargets.addEventListener('change',toggle);toggle();
  $('#swap-confirmation').innerHTML=`${next.wristSensitive?'<p class="notice amber mt-16">Use only if comfortable for your wrist. Your daily symptom checks still apply.</p>':''}${next.equipmentConfirmationRequired?`<label class="check-row mt-16"><input type="checkbox" name="equipmentConfirmed" required>I have checked the actual model or rated attachment, its setup and the permitted movement. Machine squats keep the feet grounded.</label>`:''}`;
  form.elements.variant.required=!!next.equipmentConfirmationRequired;
 };
 const filter=()=>{const previous=form.elements.exerciseId.value,q=form.elements.search.value.trim().toLowerCase(),category=form.elements.category.value;const matches=[...choices.values()].filter(option=>{const next=exById(option.exerciseId);return (!category||next.category===category)&&(!q||[next.name,next.code,...next.muscles,...next.equipment].join(' ').toLowerCase().includes(q));}).sort((a,b)=>Number(b.suggested)-Number(a.suggested)||a.name.localeCompare(b.name));form.elements.exerciseId.innerHTML=matches.map(option=>`<option value="${option.exerciseId}">${esc(option.name)}${option.suggested?' · Suggested':''}</option>`).join('');if(matches.some(option=>option.exerciseId===previous))form.elements.exerciseId.value=previous;$('#swap-count').textContent=`${matches.length} exercises`;update();};
 form.elements.search.addEventListener('input',filter);form.elements.category.addEventListener('change',filter);form.elements.exerciseId.addEventListener('change',update);filter();
 form.addEventListener('submit',async event=>{event.preventDefault();const f=new FormData(form),option=choices.get(String(f.get('exerciseId')));if(!option)return;const next=exById(option.exerciseId);try{
 const selected=structuredClone(option);
 if(form.elements.editTargets.checked){selected.targetSets=customTargets(next,{metric:String(f.get('metric')),amount:number(f,'amount'),sets:number(f,'sets'),sides:number(f,'sides'),restSec:number(f,'restSec'),rpe:number(f,'rpe')});delete selected.repRange;}
 const updated=applyAlternative(sx,selected,next,String(f.get('variant')||'standard'),f.has('equipmentConfirmed'));
 const currentOption={exerciseId:sx.exerciseId,role:sx.role,targetSets:sx.targetSets,rampUpSets:sx.rampUpSets||[],notes:sx.notes,setupSec:sx.setupSec||0,estimatedBlockMin:sx.estimatedBlockMin||0};
 for(const key of ['testProtocolId','linkedTestProtocolIds','testReferenceExerciseId','indoorSwap','equipmentSwap','symptomGate','repRange','preWorkRestSec','isRehearsal'])if(sx[key]!==undefined)currentOption[key]=structuredClone(sx[key]);
 updated.equipmentOptions=[currentOption,...(sx.equipmentOptions||[]).filter(o=>o.exerciseId!==sx.exerciseId)];
 await db.save('session_exercises',updated);closeModal();await refresh();toast('Alternative saved for this session.');}catch(err){toast(err.message,true);}});
}

function confirmEquipment(id){
 const sx=state.data.session_exercises.find(x=>x.id===id),e=exById(sx.exerciseId);
 modal('Confirm equipment setup',`<p><strong>${esc(e.name)}</strong></p><p class="mt-16">${esc(e.equipmentNotes||e.cues[0])}</p><p class="small muted mt-16">Use the actual equipment instructions or a gym instructor to check setup and permitted movement. Keep machine squats grounded. This records setup only; wrist symptoms still take priority.</p><form id="equipment-confirm-form" class="mt-16"><label>Machine model / rated attachment and settings<input name="variant" required maxlength="100" value="${esc(sx.variant==='standard'?'':sx.variant||'')}" placeholder="Your actual equipment and setup"></label><label class="check-row mt-16"><input type="checkbox" required>I have checked this setup and the prescribed movement is permitted.</label><div class="form-actions"><button class="btn btn-primary">Save setup</button></div></form>`);
 $('#equipment-confirm-form').addEventListener('submit',async event=>{event.preventDefault();try{const f=new FormData(event.target);await db.save('session_exercises',{...sx,variant:String(f.get('variant')),equipmentConfirmed:true,equipmentConfirmedAt:isoNow()});closeModal();await refresh();toast('Equipment setup saved for this session.');}catch(err){toast(err.message,true);}});
}

function renderSettings(){const s=sync.getSyncState(),p=state.prefs;return `<div class="page-heading"><div><h1>Make it yours.</h1><p>Your programme, your data, your next season.</p></div></div><div class="grid-2 align-start"><div class="stack"><section class="settings-section"><h2>Training preferences</h2><p>Small adjustments that keep the programme practical.</p><form id="preferences-form"><div class="form-grid"><label class="full">Display name<input name="displayName" maxlength="40" value="${esc(p.displayName)}"></label><label>Lower-body increment (kg)<input name="lowerIncrement" type="number" min="0.25" max="10" step="0.25" value="${p.lowerIncrement}" required></label><label>Upper-body increment (kg)<input name="upperIncrement" type="number" min="0.25" max="10" step="0.25" value="${p.upperIncrement}" required></label><label>Effort entry<select name="effortMode"><option value="rpe" ${p.effortMode==='rpe'?'selected':''}>RPE: 10 is maximal effort</option><option value="rir" ${p.effortMode==='rir'?'selected':''}>RIR: reps left in reserve</option></select></label><label>Confirmed tryout date<input name="tryoutDate" type="date" value="${esc(p.tryoutDate)}"></label><label class="full">Confirmed first game date<input name="firstGameDate" type="date" value="${esc(p.firstGameDate)}"></label><label class="check-row full"><input type="checkbox" name="weatherEnabled" ${p.weatherEnabled?'checked':''}>Fetch Brentwood weather when I open SHIFT online</label></div><p class="form-help">Tryouts are expected in June or July 2027 and the league begins in September. Leave exact dates blank until confirmed. A dated tryout reduces working sets for the preceding seven days.</p><div class="form-actions"><button class="btn btn-primary">Save preferences</button></div></form></section>
 <section class="settings-section"><h2>Own your training history</h2><p>Download a complete backup with your programme, exercise changes and logs. JSON is the simplest format for moving between the preview, Vercel, phone and Mac.</p><div class="row wrap"><button class="btn btn-secondary" data-action="export-json">${icon('download')} Export JSON</button><button class="btn btn-secondary" data-action="export-csv">${icon('download')} Export CSV</button></div><label class="mt-24">Import a SHIFT backup<input type="file" id="import-file" accept=".json,.csv,application/json,text/csv"></label><p class="form-help">Import merges newer records and preserves existing newer edits. CSV stores one full JSON record per row for lossless round-tripping. Auth credentials are never exported.</p><div class="row wrap mt-16"><a class="btn btn-ghost" href="./data/programme.json" download="shift-52-week-programme.json">Download programme JSON</a><a class="btn btn-ghost" href="./training-programme.html" target="_blank" rel="noopener">Readable programme</a></div></section>
 <section class="settings-section"><h2>Install on your devices</h2><p>On your Samsung, open the deployed address in Chrome and use Install app or Add to Home screen. On your Mac, use Chrome’s install button or Safari’s Add to Dock.</p><div class="row wrap"><button class="btn btn-primary" data-action="install">${icon('plus')} Install SHIFT</button><button class="btn btn-secondary" data-action="storage-persist">Keep offline data</button></div><p class="form-help">Open once online and wait for “Offline ready”. Browser storage can still be removed when clearing site data. Keep a separate export. Timer alerts can be limited when the browser or phone is asleep.</p><div id="offline-status" class="notice mt-16">Checking offline installation…</div></section></div>
 <div class="stack"><section class="settings-section"><div class="row-between mb-16"><h2>Optional private sync</h2><span class="badge ${s.status==='synced'?'lime':'neutral'}">${esc(s.status||'local')}</span></div><p>Use your own Supabase project to share logs between this phone and your Mac. The app remains usable without it.</p><div class="notice mb-24">${esc(s.error||s.email? s.error||'Signed in as '+s.email:'Currently using local device storage.')}<br>${state.data.sync_queue.length} queued changes${s.lastSynced?'<br>Last synced '+esc(new Date(s.lastSynced).toLocaleString('en-GB')):''}</div><form id="sync-config-form"><label>Supabase project URL<input type="url" name="url" placeholder="https://your-project.supabase.co" required></label><label class="mt-16">Publishable API key<input name="key" type="text" autocomplete="off" placeholder="sb_publishable_…" required></label><p class="form-help">Use the publishable / anon key. Never paste a secret or service_role key here. Run the supplied setup.sql in your own project first.</p><div class="form-actions"><button class="btn btn-secondary">Save connection</button></div></form><hr><form id="auth-form"><div class="form-grid"><label class="full">Email<input type="email" name="email" autocomplete="username" required value="${esc(s.email||'')}"></label><label class="full">Password<input type="password" name="password" autocomplete="current-password" minlength="8" required></label></div><div class="form-actions"><button type="button" class="btn btn-secondary" id="sign-up">Create account</button><button class="btn btn-primary">Sign in</button></div></form><div class="row wrap mt-16"><button class="btn btn-secondary" data-action="sync-now">${icon('sync')} Sync now</button><button class="btn btn-ghost" data-action="sign-out">Sign out</button><button class="btn btn-ghost" data-action="disconnect">Disconnect</button></div><p class="form-help">Sync runs while the app is open and when it reconnects. Different sites have separate browser storage. Import your backup once when moving to your Vercel address.</p></section>
 <section class="settings-section"><h2>How progression works</h2><ul class="source-list"><li>Main lifts: hit all prescribed reps within the RPE cap before the next increase.</li><li>Accessories: reach the top of the rep range across every set, then add load.</li><li>Two completed sessions with missed targets suggest a 7.5% reset.</li><li>Deloads use roughly 87.5% of the last comfortable reference and do not earn increases.</li><li>Low readiness offers fewer sets. Symptoms can pause affected work.</li><li>Different exercises, equipment variants and day templates keep separate references.</li></ul><p class="risk-note mt-16">These are editable coaching rules. The plan cannot assess an injury. Your wrist loading should follow a clinician’s examination and rehabilitation plan.</p></section>
 <section class="settings-section"><h2>Research and programme notes</h2><p>The full programme includes the source list, exercise library, testing protocols, dated weeks and the limits of the evidence.</p><a class="btn btn-secondary" href="./training-programme.html" target="_blank" rel="noopener">Read the full programme</a><details class="mt-16"><summary>Reset this device</summary><p class="small muted">Export first. This clears this site’s local programme, logs and connection. It does not delete your Supabase account or remote records.</p><button class="btn btn-danger mt-16" data-action="reset-device">Clear this device</button></details></section></div></div>`;}
async function savePreferences(prefs){state.prefs={...defaults,...prefs};await db.setMeta('preferences',state.prefs);const old=state.data.users.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];await db.save('users',{...old,displayName:state.prefs.displayName,preferences:state.prefs});}
function bindSettings(){
 $('#preferences-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await savePreferences({...state.prefs,displayName:String(f.get('displayName')||'Athlete'),lowerIncrement:number(f,'lowerIncrement'),upperIncrement:number(f,'upperIncrement'),effortMode:String(f.get('effortMode')),tryoutDate:String(f.get('tryoutDate')||''),firstGameDate:String(f.get('firstGameDate')||''),weatherEnabled:f.has('weatherEnabled')});await refresh();toast('Preferences saved.');}catch(err){toast(err.message,true);}});
 $('#sync-config-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await sync.configureSync({url:String(f.get('url')),key:String(f.get('key'))});await refresh();toast('Connection saved. Sign in to start syncing.');}catch(err){toast(err.message,true);}});
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await sync.signIn(String(f.get('email')),String(f.get('password')));await refresh();toast('Signed in. Sync is starting.');}catch(err){toast(err.message,true);}});
 $('#sign-up').addEventListener('click',async()=>{const form=$('#auth-form');if(!form.reportValidity())return;const f=new FormData(form);try{const result=await sync.signUp(String(f.get('email')),String(f.get('password')));toast(result.requiresEmailConfirmation?'Check your email to confirm the account, then sign in.':'Account created.');await refresh();}catch(err){toast(err.message,true);}});
 $('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>50*1024*1024)return toast('Choose a backup smaller than 50 MB.',true);try{const text=await file.text(),backup=file.name.toLowerCase().endsWith('.csv')?db.fromCSV(text):JSON.parse(text);const result=await db.importData(backup);await refresh();toast('Backup imported. Newer records were merged.');}catch(err){toast('Import failed: '+err.message,true);}});
 offlineReadyStatus();
}
async function offlineReadyStatus(){const target=$('#offline-status');if(!target)return;if(!('serviceWorker'in navigator)){target.textContent='This browser does not support offline installation.';return;}const registration=await navigator.serviceWorker.getRegistration();target.textContent=registration?.active?'Offline ready. The app and complete programme are cached on this device.':'Finishing the first online download. Keep this page open for a moment.';}

function timerModal(){modal('Training timers',`<div class="pill-tabs"><button class="active" data-action="stopwatch">Stopwatch</button><button data-action="rest-preset" data-seconds="90">90s rest</button><button data-action="rest-preset" data-seconds="120">120s rest</button></div><div id="modal-timer-value" class="timer-display">${timerText()}</div><p class="text-center small muted" id="modal-timer-phase">${esc(timerState().phase)}</p><div class="row wrap mt-16"><button class="btn btn-secondary" data-action="timer-pause">Pause / resume</button><button class="btn btn-ghost" data-action="timer-stop">Reset</button></div><hr><h3>Custom interval block</h3><form id="interval-form"><div class="form-grid"><label>Work seconds<input type="number" name="work" min="1" max="3600" value="15" required></label><label>Recovery seconds<input type="number" name="rest" min="0" max="3600" value="45" required></label><label>Rounds<input type="number" name="rounds" min="1" max="100" value="4" required></label></div><div class="form-actions"><button class="btn btn-primary">Start intervals</button></div></form><p class="form-help">Timers use elapsed clock time, so the displayed time catches up after a background pause. Sound and vibration depend on browser support and device settings. The stopwatch is not comparable with timing gates.</p>`);$('#interval-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);await unlockAudio();startIntervals(number(f,'work'),number(f,'rest'),number(f,'rounds'));toast('Interval timer started.');});}
function updateTimerDock(){const t=timerState(),dock=$('#timer-dock'),show=t.running||t.remaining>0||t.elapsed>0;if(!dock)return;dock.hidden=!show;if(show)dock.innerHTML=`<div class="timer-dock-inner"><div><div class="timer-mode">${esc(t.phase)}${['interval','sequence'].includes(t.mode)?` · ${t.round}/${t.rounds}`:''}</div><div class="timer-value">${timerText()}</div></div><div class="grow small muted">${t.running?'Keep the quality high.':'Timer paused'}</div><div class="timer-controls"><button class="icon-btn" data-action="timer-pause" aria-label="${t.running?'Pause':'Resume'} timer">${icon(t.running?'pause':'play')}</button><button class="icon-btn" data-action="timer-stop" aria-label="Stop timer">${icon('close')}</button></div></div>`;const modalValue=$('#modal-timer-value');if(modalValue)modalValue.textContent=timerText();const phase=$('#modal-timer-phase');if(phase)phase.textContent=t.phase+(['interval','sequence'].includes(t.mode)?` · round ${t.round} of ${t.rounds}`:'');}
async function fetchWeather(){if(!navigator.onLine)return toast('You are offline. Indoor swaps are still available.',true);try{const response=await fetch('https://api.open-meteo.com/v1/forecast?latitude=51.62&longitude=0.30&daily=precipitation_probability_max,sunset&timezone=Europe%2FLondon&forecast_days=2',{signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error('Weather unavailable');const data=await response.json(),rain=data.daily.precipitation_probability_max[0],sunset=data.daily.sunset[0]?.slice(11,16);state.weather={rain,sunset,date:today(),summary:`Today: ${rain}% chance of rain · sunset ${sunset}. ${rain>=40?'Indoor practice is a practical choice.':'Check your surface and light before shooting.'} Forecast: Open-Meteo.`};await db.setMeta('weather',state.weather);if(state.route==='today')renderApp();toast('Forecast updated. You can choose an indoor swap in the session.');}catch(err){toast('Forecast unavailable. Manual indoor swaps still work.',true);}}

function testDetail(code){
 const session=state.data.sessions.find(s=>s.id===state.sessionId),date=session?.date||state.date,r=readiness(wellnessFor(date));
 const protocol=state.data.testProtocols.find(p=>p.code===code);if(!protocol)return;
 if(r.illness||r.wristHold&&protocol.requiresClinicianClearance)return toast('Postpone this assessment until symptoms have been reviewed.',true);
 openTestModal({...ctx(),date,sessionId:session?.id},null,code);
}
async function exportBackup(format){const data=await db.exportData();if(format==='csv')download(`shift-backup-${today()}.csv`,db.toCSV(data),'text/csv;charset=utf-8');else download(`shift-backup-${today()}.json`,JSON.stringify(data,null,2));toast('Backup downloaded. Keep it somewhere you can find again.');}
function resetDevice(){modal('Clear this device',`<p>Download a backup first. This removes this site’s local logs, programme edits, sign-in and connection. Your remote account is not deleted.</p><form id="reset-form" class="mt-16"><label>Type CLEAR to confirm<input name="confirm" pattern="CLEAR" required autocomplete="off"></label><div class="form-actions"><button type="button" class="btn btn-secondary" data-action="export-json">Export backup</button><button class="btn btn-danger">Clear local data</button></div></form>`);$('#reset-form').addEventListener('submit',async e=>{e.preventDefault();try{await sync.signOut();await db.clearDatabase();location.reload();}catch(err){toast(err.message,true);}});}

document.addEventListener('click',async event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,id=button.dataset.id;
 try{switch(action){
 case 'close-modal':closeModal();break;
 case 'wellness':wellnessModal();break;
 case 'open-session':location.hash='session/'+id;break;
 case 'open-plan':state.week=weekFor(state.date)?.number||1;if(location.hash==='#plan')renderApp();else location.hash='plan';break;
 case 'select-date':state.date=button.dataset.date;renderApp();break;
 case 'choose-week':state.week=Number(button.dataset.week);state.planMode='calendar';if(state.route!=='plan')location.hash='plan';else renderApp();break;
 case 'week-prev':state.week=Math.max(1,state.week-1);renderApp();break;
 case 'week-next':state.week=Math.min(52,state.week+1);renderApp();break;
 case 'plan-mode':state.planMode=button.dataset.mode;renderApp();break;
 case 'add-session':addSession();break;
 case 'session-options':sessionOptions(id);break;
 case 'exercise-detail':exerciseDetail(id);break;
 case 'swap-exercise':swapExercise(id);break;
 case 'confirm-equipment':confirmEquipment(id);break;
 case 'test-detail':testDetail(button.dataset.code);break;
 case 'finish-session':finishSession(id);break;
 case 'toggle-reduction':state.reductions.has(id)?state.reductions.delete(id):state.reductions.add(id);renderApp();break;
 case 'effort-mode':await savePreferences({...state.prefs,effortMode:state.prefs.effortMode==='rpe'?'rir':'rpe'});await refresh();break;
 case 'begin-session':{const s=state.data.sessions.find(x=>x.id===id);await db.save('sessions',{...s,startedAt:isoNow()});await refresh();toast('Session clock started.');break;}
 case 'complete-prep':{const s=state.data.sessions.find(x=>x.id===id),key=button.dataset.part+'Done';await db.save('sessions',{...s,[key]:!s[key]});await refresh();break;}
 case 'indoor-swap':{const s=state.data.sessions.find(x=>x.id===id);await db.save('sessions',{...s,indoorSwapActive:!s.indoorSwapActive});await refresh();toast(s.indoorSwapActive?'Outdoor version selected.':'Indoor version selected. Rehearsals are not counted as shots.');break;}
 case 'remove-log':await db.remove(button.dataset.table,id);await refresh({render:false});await updateRecords();await refresh();toast('Entry removed.');break;
 case 'timers':timerModal();break;
 case 'rest-preset':await unlockAudio();startRest(Number(button.dataset.seconds));break;
 case 'preset-prescription':{const s=state.data.sessions.find(x=>x.id===state.sessionId),base=state.data.session_exercises.find(x=>x.id===button.dataset.sx);await unlockAudio();const effective=effectiveExercise(base,s),prescription=dailyPrescription(effective,readiness(wellnessFor(s.date)),{applyReduction:state.reductions.has(s.id),gameWithin48h:eventNear(s.date),tryoutTaper:taperNear(s.date)});startPrescription(prescription.targetSets);break;}
 case 'preset-interval':await unlockAudio();startIntervals(Number(button.dataset.work),Number(button.dataset.rest),Number(button.dataset.rounds));break;
 case 'stopwatch':await unlockAudio();startStopwatch();break;
 case 'timer-pause':await unlockAudio();pauseTimer();break;
 case 'timer-stop':stopTimer();break;
 case 'weather':await fetchWeather();break;
 case 'export-json':await exportBackup('json');break;
 case 'export-csv':await exportBackup('csv');break;
 case 'sync-info':location.hash='settings';break;
 case 'sync-now':{const result=await sync.syncNow();await refresh();toast(result.status==='synced'?'Sync complete.':result.error||(result.status==='local'?'Connect Supabase in Settings to enable sync.':'Sign in to your Supabase account first.'),result.status==='error');break;}
 case 'sign-out':await sync.signOut();await refresh();toast('Signed out. Your local logs remain available.');break;
 case 'disconnect':await sync.disconnectSync();await refresh();toast('Sync disconnected. Local training continues.');break;
 case 'reset-device':resetDevice();break;
 case 'storage-persist':{const result=await navigator.storage?.persist?.();toast(result?'Persistent storage allowed on this device.':'The browser manages offline storage. Keep regular JSON backups.');break;}
 case 'install':if(state.installPrompt){await state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;}else modal('Install SHIFT','<p>On Android Chrome, open the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>. On Mac Chrome, use the install icon in the address bar. Safari supports <strong>File → Add to Dock</strong>.</p><p>The app must first be opened online at its deployed HTTPS address. If it is already installed, launch it from its icon.</p><div class="form-actions"><button class="btn btn-primary" data-action="close-modal">Got it</button></div>');break;
 case 'update-app':state.updateWorker?.postMessage({type:'SKIP_WAITING'});break;
 }}catch(error){toast(error.message||'The change could not be saved. Please try again.',true);}
});
document.addEventListener('change',event=>{if(event.target.id==='week-select'){state.week=Number(event.target.value);renderApp();}});
document.addEventListener('shift-timer',updateTimerDock);
window.addEventListener('hashchange',setRoute);
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();state.installPrompt=event;});
window.addEventListener('online',()=>{renderSyncStatus();if(state.prefs.weatherEnabled)fetchWeather();});
window.addEventListener('offline',renderSyncStatus);
function renderSyncStatus(){for(const element of $$('.online-status'))element.innerHTML=syncLabel();}
let remoteRefreshTimer;
window.addEventListener('shift-data-change',event=>{if(event.detail?.source==='remote'){clearTimeout(remoteRefreshTimer);remoteRefreshTimer=setTimeout(()=>refresh({render:!$('#modal').open&&document.activeElement?.tagName!=='INPUT'&&document.activeElement?.tagName!=='TEXTAREA'}),200);}});

async function init(){
 try{const response=await fetch('./data/programme.json');if(!response.ok)throw new Error('The programme could not be loaded. Open the app online once before using it offline.');seed=await response.json();await db.initDB(seed);await refresh({render:false});state.week=weekFor(today())?.number||1;state.weather=await db.getMeta('weather',null);await sync.startSync();sync.subscribeSync(renderSyncStatus);initTimers();setRoute();if(state.prefs.weatherEnabled&&navigator.onLine)fetchWeather();
 if('serviceWorker'in navigator){try{const registration=await navigator.serviceWorker.register('./sw.js');let refreshingSW=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshingSW){refreshingSW=true;if(state.updateWorker)location.reload();}});const offer=worker=>{state.updateWorker=worker;const box=document.createElement('div');box.className='toast';box.style.pointerEvents='auto';box.innerHTML='An app update is ready. Your saved logs will stay. <button class="link-btn" data-action="update-app">Update now</button>';$('#toasts').append(box);};if(registration.waiting)offer(registration.waiting);registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)offer(worker);if(worker.state==='activated')offlineReadyStatus();});});navigator.serviceWorker.ready.then(()=>{offlineReadyStatus();if(!sessionStorage.getItem('shift-offline-ready')){toast('Offline ready. Your whole programme is available on this device.');sessionStorage.setItem('shift-offline-ready','1');}});}catch(error){toast('Offline installation could not finish. Keep the app online and try reopening it.',true);}}
 }catch(error){$('#app').innerHTML=`<main class="loading-shell"><div class="wordmark">SHIFT</div><h1 class="mt-24">Let’s reconnect.</h1><p class="mt-16">${esc(error.message)}</p><button class="btn btn-primary mt-24" id="retry-load">Try again</button><p class="mt-16"><a href="./training-programme.html">Open the readable programme</a></p></main>`;$('#retry-load').addEventListener('click',()=>location.reload());}
}
init();
